  /* 이름으로 DataFrame 을 만든다.
   * dtype 을 함께 넘겨야 float 컬럼이 int64 로 잘못 추론되지 않는다
   * (JS 는 1 과 1.0 을 구분하지 못한다 — core/CLAUDE.md 참조). */
  var K2 = "#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{|}", K2_NA = 8099;
